// Build-time helpers: project tours onto the base map (src/data/basemap.json, generated by
// scripts/basemap/) and turn them into SVG paths. Runs in Astro frontmatter only.
import basemap from '../data/basemap.json';
import { tours, type LonLat, type Tour } from '../data/tours';

const { lon0, lat0, R, X0, Y1, scale } = basemap.proj;
const rad = Math.PI / 180;
const s0 = Math.sin(lat0 * rad);
const c0 = Math.cos(lat0 * rad);

export const MAP_W = basemap.W;
export const MAP_H = basemap.H;

/** Lambert azimuthal equal-area (spherical), same as scripts/basemap/proj.py, in viewBox units. */
export function project([lon, lat]: LonLat): [number, number] {
  const p = lat * rad;
  const dl = (lon - lon0) * rad;
  const k = Math.sqrt(2 / (1 + s0 * Math.sin(p) + c0 * Math.cos(p) * Math.cos(dl)));
  const x = R * k * Math.cos(p) * Math.sin(dl);
  const y = R * k * (c0 * Math.sin(p) - s0 * Math.cos(p) * Math.cos(dl));
  return [(x - X0) * scale, (Y1 - y) * scale];
}

function haversineKm(a: LonLat, b: LonLat) {
  const dLat = (b[1] - a[1]) * rad;
  const dLon = (b[0] - a[0]) * rad;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a[1] * rad) * Math.cos(b[1] * rad) * Math.sin(dLon / 2) ** 2;
  return 2 * 6371.0088 * Math.asin(Math.sqrt(h));
}

type XY = [number, number];

// Douglas-Peucker in viewBox units, so long GPX tracks stay small in the page.
function simplify(pts: XY[], eps: number): XY[] {
  if (pts.length < 3) return pts;
  const keep = new Uint8Array(pts.length);
  keep[0] = keep[pts.length - 1] = 1;
  const stack: [number, number][] = [[0, pts.length - 1]];
  while (stack.length) {
    const [i, j] = stack.pop()!;
    const [ax, ay] = pts[i];
    const [bx, by] = pts[j];
    const dx = bx - ax;
    const dy = by - ay;
    const len = Math.hypot(dx, dy);
    let best = -1;
    let bestD = eps;
    for (let k = i + 1; k < j; k++) {
      // Distance to the chord, or to the point itself when both ends coincide (a loop such as Bonn to Bonn).
      const d = len > 1e-9
        ? Math.abs(dy * (pts[k][0] - ax) - dx * (pts[k][1] - ay)) / len
        : Math.hypot(pts[k][0] - ax, pts[k][1] - ay);
      if (d > bestD) { bestD = d; best = k; }
    }
    if (best > 0) {
      keep[best] = 1;
      stack.push([i, best], [best, j]);
    }
  }
  return pts.filter((_, k) => keep[k]);
}

const f = (v: number) => (Math.round(v * 100) / 100).toString();

function polyline(pts: XY[]) {
  return pts.map(([x, y], i) => `${i ? 'L' : 'M'}${f(x)} ${f(y)}`).join('');
}

// Catmull-Rom through hand-placed points, as cubic Béziers.
function smooth(pts: XY[]) {
  if (pts.length < 3) return polyline(pts);
  let d = `M${f(pts[0][0])} ${f(pts[0][1])}`;
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[Math.max(0, i - 1)];
    const p1 = pts[i];
    const p2 = pts[i + 1];
    const p3 = pts[Math.min(pts.length - 1, i + 2)];
    const c1: XY = [p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6];
    const c2: XY = [p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6];
    d += `C${f(c1[0])} ${f(c1[1])} ${f(c2[0])} ${f(c2[1])} ${f(p2[0])} ${f(p2[1])}`;
  }
  return d;
}

// GPX files in src/data/tours/, read at build time.
const gpxFiles = import.meta.glob<string>('../data/tours/*.gpx', { query: '?raw', import: 'default', eager: true });

function readGpx(name: string): LonLat[][] {
  const raw = gpxFiles[`../data/tours/${name}`];
  if (!raw) throw new Error(`tours.ts: GPX file not found: src/data/tours/${name}`);
  const segs = raw.split(/<trkseg\b|<rte\b/).slice(1);
  const parts = (segs.length ? segs : [raw]).map((seg) =>
    [...seg.matchAll(/<(?:trkpt|rtept)\b([^>]*)>/g)].map((m) => {
      const lat = Number(/\blat="([^"]+)"/.exec(m[1])?.[1]);
      const lon = Number(/\blon="([^"]+)"/.exec(m[1])?.[1]);
      return [lon, lat] as LonLat;
    }),
  );
  return parts.filter((p) => p.length > 1);
}

export interface ResolvedTour extends Tour {
  km: number;
  /** Track as an SVG path in base-map units. */
  d: string;
  ferryD: string;
  /** x0 y0 x1 y1 of the track, ferries and stops. */
  bbox: [number, number, number, number];
  stopsXY: { name: string; x: number; y: number }[];
}

function resolve(t: Tour): ResolvedTour {
  let parts: LonLat[][];
  let d: string;
  let km: number;
  if ('gpx' in t.track) {
    parts = readGpx(t.track.gpx);
    km = parts.reduce((sum, p) => sum + p.slice(1).reduce((s2, q, i) => s2 + haversineKm(p[i], q), 0), 0);
    d = parts.map((p) => polyline(simplify(p.map(project), 0.12))).join('');
  } else {
    parts = t.track.parts;
    km = parts.reduce((sum, p) => sum + p.slice(1).reduce((s2, q, i) => s2 + haversineKm(p[i], q), 0), 0) * 1.25;
    d = parts.map((p) => smooth(p.map(project))).join('');
  }
  const ferries = t.ferries ?? [];
  const ferryD = ferries.map((p) => smooth(p.map(project))).join('');
  const all = [...parts.flat(), ...ferries.flat(), ...t.stops.map((x) => x.at)].map(project);
  const xs = all.map((p) => p[0]);
  const ys = all.map((p) => p[1]);
  return {
    ...t,
    km: Math.round(t.km ?? km),
    d,
    ferryD,
    bbox: [Math.min(...xs), Math.min(...ys), Math.max(...xs), Math.max(...ys)],
    stopsXY: t.stops.map((x) => {
      const [px, py] = project(x.at);
      return { name: x.name, x: px, y: py };
    }),
  };
}

export const resolvedTours: ResolvedTour[] = tours.map(resolve);


export const basemapPaths = {
  land: basemap.land,
  lakes: basemap.lakes,
  borders: basemap.borders,
  rivers: basemap.rivers,
};
